    pub fn resolve(&self, model: &str, thinking: &str) -> Result<ModelChoice, ModelError> {
        let (wanted_provider, wanted_model, spec_thinking) = parse_spec(model);
        let level = normalize_thinking(if thinking.trim().is_empty() {
            &spec_thinking
        } else {
            thinking
        })?;
        if wanted_model.is_empty() {
            return Err(ModelError("no model was named".into()));
        }
        if self.entries.is_empty() {
            if wanted_provider.is_empty() {
                return Err(ModelError(format!(
                    "I can't check which provider serves {}. Say it as provider slash model.",
                    wanted_model
                )));
            }
            return Ok(ModelChoice {
                provider: wanted_provider,
                model: wanted_model,
                thinking: level,
            });
        }
        let key = normalize(&wanted_model);
        let pool = self
            .entries
            .iter()
            .filter(|entry| {
                wanted_provider.is_empty()
                    || normalize(&entry.provider) == normalize(&wanted_provider)
            })
            .collect::<Vec<_>>();
        if pool.is_empty() {
            let mut providers = self
                .entries
                .iter()
                .map(|entry| entry.provider.as_str())
                .collect::<Vec<_>>();
            providers.sort_unstable();
            providers.dedup();
            return Err(ModelError(format!(
                "there is no provider called {} here. I have {}.",
                wanted_provider,
                providers.join(", ")
            )));
        }
        let exact = pool
            .iter()
            .copied()
            .filter(|entry| normalize(&entry.model) == key)
            .collect::<Vec<_>>();
        let matches: Vec<&CatalogEntry> = if exact.is_empty() {
            pool.into_iter()
                .filter(|entry| normalize(&entry.model).contains(&key))
                .collect()
        } else {
            exact
        };
        if matches.is_empty() {
            return Err(ModelError(format!(
                "I don't have a model matching {}",
                wanted_model
            )));
        }
        let mut distinct = matches
            .iter()
            .map(|entry| (entry.provider.as_str(), entry.model.as_str()))
            .collect::<Vec<_>>();
        distinct.sort_unstable();
        distinct.dedup();
        if distinct.len() > 1 {
            let names = distinct
                .iter()
                .map(|(provider, model)| format!("{provider}/{model}"))
                .collect::<Vec<_>>()
                .join(", ");
            return Err(ModelError(format!(
                "{} is ambiguous here. It could be {}. Which one?",
                wanted_model, names
            )));
        }
        let entry = matches[0];
        if !level.is_empty() && level != "off" && !entry.thinks {
            return Err(ModelError(format!(
                "{} has no thinking levels, so I can't set {}",
                entry.model, level
            )));
        }
        Ok(ModelChoice {
            provider: entry.provider.clone(),
            model: entry.model.clone(),
            thinking: level,
        })
    }
}

pub async fn fetch_catalog(argv: &[String]) -> ModelCatalog {
    let mut command = Command::new(argv.first().map(String::as_str).unwrap_or(""));
    command
        .args(argv.iter().skip(1))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    crate::pi_client::isolate_process(&mut command);
    // An empty catalog is not an error the caller ever hears about — it just
    // narrows what models may be requested. Without these lines, "the model I
    // asked for was refused" and "listing models never worked on that host"
    // look identical from outside.
    let listing = argv.join(" ");
    let mut child = match command.spawn() {
        Ok(child) => child,
        Err(error) => {
            tracing::warn!(command = %listing, %error, "could not list models");
            return ModelCatalog {
                entries: Vec::new(),
            };
        }
    };
    let process_guard = crate::pi_client::ProcessTreeGuard::new(&child);
    let stdout_task = child.stdout.take().map(|mut output| {
        tokio::spawn(async move {
            crate::pi_client::drain_bounded(&mut output, CATALOG_OUTPUT_LIMIT).await
        })
    });
    let stderr_task = child.stderr.take().map(|mut output| {
        tokio::spawn(async move {
            crate::pi_client::drain_bounded(&mut output, CATALOG_ERROR_LIMIT).await
        })
    });
    let status = match timeout(LIST_TIMEOUT, child.wait()).await {
        Ok(Ok(status)) => {
            process_guard.disarm();
            status
        }
        outcome => {
            match outcome {
                Ok(Err(error)) => {
                    tracing::warn!(command = %listing, %error, "listing models failed")
                }
                _ => tracing::warn!(
                    command = %listing,
                    timeout = ?LIST_TIMEOUT,
                    "listing models timed out"
                ),
            }
            crate::pi_client::terminate_process(&mut child).await;
            process_guard.disarm();
            if let Some(task) = stdout_task {
                task.abort();
            }
            if let Some(task) = stderr_task {
                task.abort();
            }
            return ModelCatalog {
                entries: Vec::new(),
            };
        }
    };
    let stdout = match stdout_task {
        Some(task) => task.await.unwrap_or_default(),
        None => crate::pi_client::BoundedOutput::default(),
    };
    if let Some(task) = stderr_task {
        let _ = task.await;
    }
    if !status.success() || stdout.truncated {
        return ModelCatalog {
            entries: Vec::new(),
        };
    }
    ModelCatalog::parse(&String::from_utf8_lossy(&stdout.bytes))
}

#[cfg(test)]
mod tests {
    use super::*;
    const TABLE: &str = "provider model context max-out thinking images\nanthropic claude-opus-5 1M 128K yes yes\nanthropic claude-sonnet-5 1M 128K yes yes\nopenai claude-sonnet-5 1M 128K yes yes\ngroq llama-4-fast 128K 8K no no\n";
    #[test]
    fn parses_and_normalizes_specs() {
        assert_eq!(
            parse_spec("anthropic/claude-opus-5:high"),
            ("anthropic".into(), "claude-opus-5".into(), "high".into())
        );
        assert_eq!(parse_spec("  "), ("".into(), "".into(), "".into()));
    }
    #[test]
    fn resolves_digits_and_rejects_ambiguity() {
        let catalog = ModelCatalog::parse(TABLE);
        assert_eq!(
            catalog.resolve("opus five", "").unwrap().spec(),
            "anthropic/claude-opus-5"
        );
        assert!(catalog
            .resolve("sonnet 5", "")
            .unwrap_err()
            .to_string()
            .contains("openai/claude-sonnet-5"));
        assert_eq!(
            catalog.resolve("groq/llama 4 fast", "").unwrap().spec(),
            "groq/llama-4-fast"
        );
    }
    #[test]
    fn validates_thinking_and_pins_specs() {
        assert_eq!(
            normalize_thinking("set thinking to medium").unwrap(),
            "medium"
        );
        assert_eq!(normalize_thinking("maximum").unwrap(), "max");
        assert_eq!(normalize_thinking("no thinking").unwrap(), "off");
        assert_eq!(normalize_thinking("without thinking").unwrap(), "off");
        assert_eq!(
            normalize_thinking("thinking level x high").unwrap(),
            "xhigh"
        );
        assert!(normalize_thinking("ludicrous").is_err());
        assert_eq!(
            pin_thinking("anthropic/opus", "medium"),
            "anthropic/opus:medium"
        );
        assert_eq!(
            pin_thinking("anthropic/opus:max", "medium"),
            "anthropic/opus:max"
        );
    }
    #[test]
    fn empty_catalog_only_accepts_qualified_models() {
        let catalog = ModelCatalog { entries: vec![] };
        assert!(catalog.resolve("opus five", "").is_err());
        assert_eq!(
            catalog.resolve("anthropic/opus", "high").unwrap().spec(),
            "anthropic/opus:high"
        );
    }

    #[tokio::test]
    async fn catalog_command_success_and_failure_are_degraded_safely() {
        let table = "printf 'provider model context max-out thinking images\\nanthropic opus 1M 128K yes yes\\n'";
        let catalog = fetch_catalog(&["sh".into(), "-c".into(), table.into()]).await;
        assert_eq!(catalog.entries.len(), 1);
        assert_eq!(catalog.entries[0].provider, "anthropic");

        let failed =
            fetch_catalog(&["sh".into(), "-c".into(), "printf broken >&2; exit 9".into()]).await;
        assert!(failed.entries.is_empty());
    }
}

